// a lista vem um comando por item; se vier inteira num item só, desembrulha
let comandos = $input.all().map(i => i.json);
if (comandos.length === 1 && Array.isArray(comandos[0].data)) {
  comandos = comandos[0].data;
}

const categorias = {
  general: 'Geral',
  moderation: 'Moderação',
  utility: 'Utilidade',
  music: 'Música',
  anime: 'Anime',
  fun: 'Diversão',
  owner: 'Dono',
};

const código = texto => (texto ? '`' + texto + '`' : '—');
const célula = texto => String(texto ?? '').replace(/\|/g, '\\|');

const linhas = [
  '# Comandos do AlephBot',
  '',
  `${comandos.length} comandos, tirados de \`/api/v1/commands\` pelo n8n.`,
  '',
];

const conhecidas = Object.keys(categorias);
const grupos = [
  ...conhecidas.map(chave => [categorias[chave], comandos.filter(c => c.category === chave)]),
  ['Outros', comandos.filter(c => !conhecidas.includes(c.category))],
];

for (const [nome, daqui] of grupos) {
  if (daqui.length === 0) continue;

  linhas.push(`## ${nome}`, '', '| Comando | Barra | Prefixo | Atalhos | O que faz |', '|:--|:--|:--|:--|:--|');

  for (const c of daqui) {
    const atalhos = (c.aliases ?? []).map(código).join(', ') || '—';
    linhas.push(`| ${célula(c.name)} | ${código(c.slash)} | ${código(c.text)} | ${atalhos} | ${célula(c.description)} |`);
  }

  linhas.push('');
}

const markdown = linhas.join('\n');

// só segue quando a lista mudou: o arquivo é regravado uma vez por mudança
const memória = $getWorkflowStaticData('global');
if (memória.markdown === markdown) {
  return [];
}
memória.markdown = markdown;

return [{ json: { markdown, total: comandos.length } }];
